  computed: {
    // Calendar computed properties
    currentMonthYear() {
      return `${this.currentDate.getFullYear()}年${this.currentDate.getMonth() + 1}月`;
    },
    selectedDateStr() {
      if (!this.selectedDate) return "";
      return `${this.selectedDate.getFullYear()}年${this.selectedDate.getMonth() + 1}月${this.selectedDate.getDate()}日`;
    },
    selectedDateAppointments() {
      if (!this.selectedDate) return [];
      return this.appointments.filter(apt => apt.date.getDate() === this.selectedDate.getDate() && apt.date.getMonth() === this.selectedDate.getMonth() && apt.date.getFullYear() === this.selectedDate.getFullYear());
    },
    calendarDays() {
      const year = this.currentDate.getFullYear();
      const month = this.currentDate.getMonth();
      const firstDayOfMonth = new Date(year, month, 1);
      const lastDayOfMonth = new Date(year, month + 1, 0);
      const days = [];

      // 添加上月剩余日期
      const firstDayWeekday = firstDayOfMonth.getDay();
      const prevMonthLastDay = new Date(year, month, 0).getDate();
      for (let i = firstDayWeekday - 1; i >= 0; i--) {
        days.push({
          date: new Date(year, month - 1, prevMonthLastDay - i),
          dayOfMonth: prevMonthLastDay - i,
          currentMonth: false,
          hasAppointment: false,
          appointmentTypes: []
        });
      }

      // 添加当月日期
      for (let i = 1; i <= lastDayOfMonth.getDate(); i++) {
        const currentDay = new Date(year, month, i);
        const dayAppointments = this.appointments.filter(apt => apt.date.getDate() === currentDay.getDate() && apt.date.getMonth() === currentDay.getMonth() && apt.date.getFullYear() === currentDay.getFullYear());
        days.push({
          date: currentDay,
          dayOfMonth: i,
          currentMonth: true,
          hasAppointment: dayAppointments.length > 0,
          appointmentTypes: [...new Set(dayAppointments.map(apt => apt.type))]
        });
      }

      // 添加下月开始日期
      const remainingDays = 42 - days.length;
      for (let i = 1; i <= remainingDays; i++) {
        days.push({
          date: new Date(year, month + 1, i),
          dayOfMonth: i,
          currentMonth: false,
          hasAppointment: false,
          appointmentTypes: []
        });
      }
      return days;
    }
  },
  methods: {
    // Calendar methods
    isCurrentDate(date) {
      const today = new Date();
      return date.getDate() === today.getDate() && date.getMonth() === today.getMonth() && date.getFullYear() === today.getFullYear();
