      this.initTrendChart("newPatientsChart", this.stats.newPatientsChartData, this.stats.newPatientsTrend > 0 ? "#67C23A" : "#F56C6C");
    },
    initTrendChart(refName, data, color) {
      const chartDom = this.$refs[refName];
      const myChart = this.$echarts.init(chartDom);
      const option = {
        grid: {
          left: 0,
          right: 0,
          top: 0,
          bottom: 0
        },
        xAxis: {
          type: "category",
          show: false,
          boundaryGap: false
        },
        yAxis: {
          type: "value",
          show: false
        },
        series: [{
          data: data,
          type: "line",
          smooth: true,
          symbol: "none",
          areaStyle: {
            color: {
              type: "linear",
              x: 0,
              y: 0,
              x2: 0,
              y2: 1,
              colorStops: [{
                offset: 0,
                color: color // 渐变起始颜色
              }, {
                offset: 1,
                color: "rgba(255, 255, 255, 0.1)" // 渐变结束颜色
              }]
            }
          },
          lineStyle: {
            color: color
          }
        }]
      };
      myChart.setOption(option);

      // 保存图表实例以便在窗口大小变化时重新渲染
      if (!this.charts) {
        this.charts = {};
      }
      this.charts[refName] = myChart;
    },
    handleResize() {
      if (this.charts) {
        Object.values(this.charts).forEach(chart => {
          chart.resize();
        });
      }
    }
  },
  mounted() {
